effect.shader:
const float PI = 3.14159265;

// Converte da fase (x·aspect, y) de volta para UV (x, y).
vec2 paraUv(vec2 v) { return vec2(v.x / max(acAspect, 1e-4), v.y); }

/**
 * Coroa de 8 amostras ao redor de `ph` no raio `raio` (em unidades de fase,
 * onde 1 = altura da imagem). Devolve (rampa, normal.x, normal.y):
 *   rampa  — 1 no interior plano, ~0 exatamente na borda, 0 fora
 *   normal — direção "para fora" da superfície do chanfro (normalizada)
 */
vec3 bordaEm(vec2 ph, float raio) {
    float media = texture(inputImg, paraUv(ph)).a * 0.2;
    vec2 soma = vec2(0.0);
    for (int i = 0; i < 8; i++) {
        float ang = float(i) * 0.78539816; // PI/4
        vec2 dir = vec2(cos(ang), sin(ang));
        float a = texture(inputImg, paraUv(ph + dir * raio)).a;
        media += a * 0.1;
        soma -= dir * a;
    }
    float comp = length(soma);
    return vec3(media, comp > 1e-5 ? soma / comp : vec2(0.0));
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);
    if (original.a <= 0.0) { fragColor = original; return; }

    vec2 ph = vec2(acScreenNorm.x * acAspect, acScreenNorm.y);

    // edgeThickness em pixels → raio em unidades de fase (1 = altura)
    float raio = max(edgeThickness, 0.5) * acTexelSize.y;

    vec3 borda = bordaEm(ph, raio);
    float rampa  = clamp(borda.x, 0.0, 1.0);
    vec2  normal = borda.yz;

    // Inclinação triangular: 0 no platô e na borda dura, máximo na meia-borda.
    float inclinacao = (1.0 - abs(rampa * 2.0 - 1.0)) * lightIntensity;

    float ang = lightAngle * PI / 180.0;
    vec2 luz = vec2(cos(ang), -sin(ang));
    float voltado = dot(normal, luz);

    float claro  = clamp(max( voltado, 0.0) * inclinacao, 0.0, 1.0);
    float escuro = clamp(max(-voltado, 0.0) * inclinacao, 0.0, 1.0);

    vec3 cor = original.rgb;
    cor = mix(cor, lightColor.rgb, claro);
    cor = mix(cor, vec3(0.0),      escuro);

    fragColor = vec4(cor, original.a);
}
